#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
datastat 接口自动化测试用例（pytest）

本文件由 generate_test_cases.py 从 MeterSphere 接口定义自动生成，**请勿手工大改**；
接口定义变更后重跑生成器即可再生成。

特点:
- 自包含：所有用例的请求数据已固化为字面量，不依赖 api/ 目录，也不依赖 utils.py
- 标准 pytest：用例通过 @pytest.mark.parametrize 展开，可用 -k / -m 正常筛选

用例规模: 958 条
  - 正向 仅必填参数    361 条
  - 正向 必填+可选全参  361 条
  - 反向 缺失必填参数   108 条
  - 反向 非法格式参数   128 条

用法:
    py -m pytest test_cases.py -v                          # 全量
    py -m pytest test_cases.py -m positive -v              # 只跑正向
    py -m pytest test_cases.py -m negative -v              # 只跑反向
    py -m pytest test_cases.py --module=datastat -v        # 只跑指定模块
    py -m pytest test_cases.py -n 8 --html=test_report.html --self-contained-html

    py test_cases.py --all --report                        # 命令行入口（等价于上面最后一条）

凭证:
    部分接口要求 header 携带 token 或管理员 api-key（接口定义里未提供有效取值），
    通过环境变量注入：
        set DATASTAT_TOKEN=<token>        # 普通 token
        set DATASTAT_API_KEY=<api-key>    # 管理员 key（admin_token 权限）
    另有一批接口需要业务鉴权，用 --auth-token 传入 Bearer Token。

    **未提供凭证时，需鉴权的用例会被自动 skip**（而不是发请求拿 403）。
    加 --run-unauthorized 可强制执行，用于观察未授权分支的响应：
        py test_cases.py --all --run-unauthorized
"""
import argparse
import json
import os
import subprocess
import sys
import time
