import pytest
import requests


# ==================== 默认配置 ====================
DEFAULT_BASE_URL = "https://datastat2.test.osinfra.cn/server"
# 默认 60 秒：部分统计接口后端自身有 30 秒内部超时，
# 客户端超时必须大于它，否则会因客户端先断开而报请求异常，掩盖真实的服务端错误
DEFAULT_TIMEOUT = 60

# 正向用例的响应时间阈值（毫秒），超过则标记 xfail
RESPONSE_TIME_THRESHOLD_MS = 10000

# 视为业务成功的 code 取值。
#
# 本服务端的约定（由实测响应确认）:
#   code=1   成功，message 为 "success"
#   code=0   参数校验失败，message 形如 "参数[community]为必填项" / "xxx 格式非法"
#   code=-1  系统内部出现错误
#   code=403 用户没有权限
# 因此只有 1 是成功。注意：旧版脚本正向用例误把 0 也算作成功
# （code not in (1, 200, 0, "success")），导致 48 条实际参数校验失败的正向用例
# 被静默放行，报告中完全不可见。
SUCCESS_CODES = (1,)

# 业务码非成功时，message 命中这些关键字则判定为"测试环境数据缺失"，标记 xfail
DATA_MISSING_KEYWORDS = ("不存在", "未找到", "空", "no data", "not found")


# 需要凭证的 header -> 读取凭证的环境变量名
# 这些接口在接口定义里没给 header 值，运行时从环境变量补齐。
# 未设置时请求照发，后端会返回 "header[xxx]为必填项"。
CREDENTIAL_ENV = {
    "api-key": "DATASTAT_API_KEY",
    "token": "DATASTAT_TOKEN",
}


# ==================== 命令行选项解析 ====================

def _get_cli_option(flag, default=None):
    """从 sys.argv 解析选项值（支持 --flag=val 和 --flag val 两种形式）"""
    argv = sys.argv
    for i, arg in enumerate(argv):
        if arg.startswith(flag + "="):
            return arg.split("=", 1)[1]
        if arg == flag and i + 1 < len(argv):
            return argv[i + 1]
    return default


def _filter_by_module(cases):
    """按 --module 选项过滤用例；未指定时返回全部"""
    target = _get_cli_option("--module", "")
    if not target:
        return cases
    return [c for c in cases if c["module"] == target]


def _ids(cases):
    return [c["id"] for c in cases]


# ==================== pytest Fixture ====================

@pytest.fixture(scope="session")
def http_session():
    """创建带认证信息的 requests Session"""
    session = requests.Session()
    token = _get_cli_option("--auth-token", "")
    if token:
        session.headers.update({"Authorization": "Bearer " + token})
    yield session
    session.close()


@pytest.fixture
def timeout():
    """请求超时时间（秒）"""
    val = _get_cli_option("--timeout", str(DEFAULT_TIMEOUT))
    try:
        return int(val)
    except (ValueError, TypeError):
        return DEFAULT_TIMEOUT


# ==================== 请求与校验工具 ====================

def _has_auth_token():
    """是否提供了业务鉴权 Token"""
    return bool(_get_cli_option("--auth-token", ""))


def _has_credential(names):
    """指定的凭证 header 是否都能从环境变量取到值"""
    for name in names or []:
        env_name = CREDENTIAL_ENV.get(name)
        if not env_name or not os.environ.get(env_name, ""):
            return False
    return True


def _run_unauthorized():
    """是否强制执行需鉴权的用例（默认不执行）"""
    return "--run-unauthorized" in sys.argv


def _skip_if_unauthorized(case):
    """
    未提供凭证时跳过需要鉴权的用例。

    两类判定：
    - needs_auth：生成阶段实测返回 403 的接口，需 --auth-token
    - cred_headers：需要 header 凭证（token / api-key）的接口，需对应环境变量

    加 --run-unauthorized 可强制执行，用于观察未授权分支的响应。
    """
    if _run_unauthorized():
        return

    cred = case.get("cred_headers")
    if cred and not _has_credential(cred):
        envs = ", ".join(CREDENTIAL_ENV.get(n, n) for n in cred)
        pytest.skip("需要凭证 header %s，未设置环境变量 %s（加 --run-unauthorized 可强制执行）"
                    % (cred, envs))

    if case.get("needs_auth") and not _has_auth_token():
        pytest.skip("需要鉴权（实测返回 code=403），未提供 --auth-token"
                    "（加 --run-unauthorized 可强制执行）")


def _build_headers(case):
    """
    组装请求 header：接口定义里的固定 header + 从环境变量补齐的凭证 header。

    需要凭证的接口（case["cred_headers"] 非空）在未设置对应环境变量时，
    header 缺失，后端会返回 "header[xxx]为必填项"——属预期行为，不视为失败。
    """
    headers = dict(case.get("headers") or {})
    for name in case.get("cred_headers") or []:
        env_name = CREDENTIAL_ENV.get(name)
        value = os.environ.get(env_name, "") if env_name else ""
        if value:
            headers[name] = value
    return headers


def _make_request(http_session, base_url, case, timeout):
    """按用例数据发送 HTTP 请求"""
    url = base_url + case["path"]
    method = case["method"]

    kwargs = {"timeout": timeout}
    if case.get("params"):
        kwargs["params"] = case["params"]
    if case.get("body") is not None:
        kwargs["json"] = case["body"]
    headers = _build_headers(case)
    if headers:
        kwargs["headers"] = headers

    if method == "GET":
        return http_session.get(url, **kwargs)
    if method == "POST":
        return http_session.post(url, **kwargs)
    if method == "PUT":
        return http_session.put(url, **kwargs)
    if method == "DELETE":
        return http_session.delete(url, **kwargs)
    raise ValueError("不支持的 HTTP 方法: " + str(method))


def _safe_json_loads(text):
    """安全解析 JSON，失败返回 None"""
    try:
        return json.loads(text)
    except (json.JSONDecodeError, TypeError):
        return None


_TYPE_CHECKS = {
    "object": dict,
    "array": list,
    "string": str,
    "integer": int,
    "int": int,
    "long": int,
    "boolean": bool,
    "float": float,
    "double": float,
    "number": (int, float),
}


def _validate_schema(resp_json, resp_def):
    """
    校验响应顶层结构是否符合接口定义。

    只校验顶层字段：检查 code / message 是否存在，以及各顶层字段的数据类型
    是否与定义一致。返回差异描述列表（空列表表示无差异）。
    """
    errors = []
    if not isinstance(resp_json, dict):
        return ["响应不是 JSON 对象"]

    if "code" not in resp_json:
        errors.append("响应缺少 'code' 字段")
    if "message" not in resp_json:
        errors.append("响应缺少 'message' 字段")

    if not resp_def:
        return errors

    for name, dtype in resp_def.items():
        if name not in resp_json:
            continue
        expected = _TYPE_CHECKS.get(str(dtype).lower())
        if expected is None:
            continue
        actual = resp_json[name]
        # bool 是 int 的子类，单独排除避免误判
        if expected is int and isinstance(actual, bool):
            errors.append("%s: 期望 %s，实际为 bool" % (name, dtype))
        elif not isinstance(actual, expected):
            errors.append("%s: 期望 %s，实际为 %s" % (name, dtype, type(actual).__name__))
    return errors


def _report_negative_result(response):
    """反向用例的通用结果判定：期望返回业务错误码或 HTTP 4xx"""
    resp_json = _safe_json_loads(response.text)
    if resp_json and "code" in resp_json:
        code = resp_json["code"]
        if code in SUCCESS_CODES:
            return None, code, resp_json.get("message", "")
        return "biz_error", code, resp_json.get("message", "")
    if response.status_code >= 400:
        return "http_error", None, ""
    return "no_error", None, ""



