_CASES_NORMAL = _filter_by_module(_ALL_CASES_NORMAL)
_CASES_OPTIONAL = _filter_by_module(_ALL_CASES_OPTIONAL)
_CASES_MISSING = _filter_by_module(_ALL_CASES_MISSING)
_CASES_INVALID = _filter_by_module(_ALL_CASES_INVALID)


# ==================== 正向测试 ====================

class TestApiPositive:
    """正向测试：使用正常参数调用接口，验证返回结构和基本可用性"""

    @pytest.mark.positive
    @pytest.mark.parametrize("case", _CASES_NORMAL, ids=_ids(_CASES_NORMAL))
    def test_normal_request(self, http_session, base_url, case, timeout):
        """
        正常参数调用接口（仅传必填参数）
        - 验证 HTTP 状态码 < 500
        - 验证响应时间未超阈值
        - 校验响应顶层结构与接口定义是否一致
        - 记录业务码（不强制断言，测试环境数据可能不完整）
        """
        _skip_if_unauthorized(case)

        start_time = time.time()
        try:
            response = _make_request(http_session, base_url, case, timeout)
        except requests.RequestException as e:
            pytest.fail("请求异常: %s" % e)
        elapsed_ms = (time.time() - start_time) * 1000

        print("\n[正向] [%s] %s%s" % (case["method"], base_url, case["path"]))
        print("  Params: %s" % case["params"])
        if case.get("body"):
            print("  Body: %s" % case["body"])
        print("  Status: %d, Time: %.0fms" % (response.status_code, elapsed_ms))

        # 1. 状态码：允许 2xx/3xx/4xx，不允许 5xx
        assert response.status_code < 500, \
            "服务器内部错误: HTTP %d, 响应: %s" % (response.status_code, response.text[:500])

        # 2. 响应时间
        if elapsed_ms > RESPONSE_TIME_THRESHOLD_MS:
            pytest.xfail("响应时间超过阈值: %.0fms > %dms" % (elapsed_ms, RESPONSE_TIME_THRESHOLD_MS))

        # 3. 响应结构
        resp_json = _safe_json_loads(response.text)
        if resp_json is not None:
            struct_errors = _validate_schema(resp_json, case.get("resp_def"))
            if struct_errors:
                # 结构差异记录为警告，不直接失败
                print("  [结构警告] %s" % struct_errors)

            # 4. 业务码
            if "code" in resp_json:
                code = resp_json["code"]
                message = resp_json.get("message", "")
                if code not in SUCCESS_CODES:
                    msg_lower = str(message).lower()
                    if any(k in msg_lower for k in DATA_MISSING_KEYWORDS):
                        pytest.xfail("数据相关: code=%s, message=%s" % (code, message))
                    print("  [业务码注意] code=%s, message=%s" % (code, message))
        else:
            # 接口定义了 JSON responseBody 却返回非 JSON，说明请求未真正命中接口
            # （典型场景：前端 SPA 的 catch-all 路由返回 200 + HTML，会造成"假通过"）
            content_type = response.headers.get("Content-Type", "")
            print("  [非 JSON 响应] Content-Type: %s" % content_type)
            if case.get("has_resp_body"):
                pytest.fail(
                    "接口定义包含 responseBody 但实际返回非 JSON (Content-Type=%s)，"
                    "请求可能未命中真实接口。响应片段: %s" % (content_type, response.text[:200])
                )

    @pytest.mark.positive
    @pytest.mark.parametrize("case", _CASES_OPTIONAL, ids=_ids(_CASES_OPTIONAL))
    def test_optional_params(self, http_session, base_url, case, timeout):
        """
        包含可选参数调用接口（必填 + 可选全部填充）
        - 验证接口在完整参数下仍正常工作，不返回 5xx
        """
        _skip_if_unauthorized(case)

        start_time = time.time()
        try:
            response = _make_request(http_session, base_url, case, timeout)
        except requests.RequestException as e:
            pytest.fail("请求异常: %s" % e)
        elapsed_ms = (time.time() - start_time) * 1000

        print("\n[正向-全参] [%s] %s%s" % (case["method"], base_url, case["path"]))
        print("  Status: %d, Time: %.0fms" % (response.status_code, elapsed_ms))

        assert response.status_code < 500, \
            "服务器内部错误: HTTP %d" % response.status_code


# ==================== 反向测试 ====================

class TestApiNegative:
    """反向测试：使用非法/缺失参数调用接口，验证错误处理能力"""

    @pytest.mark.negative
    @pytest.mark.parametrize("case", _CASES_MISSING, ids=_ids(_CASES_MISSING))
    def test_missing_required_params(self, http_session, base_url, case, timeout):
        """
        缺少必填参数
        - 不传任何必填参数直接请求
        - 期望返回 HTTP 4xx 或非成功业务码
        """
        _skip_if_unauthorized(case)

        try:
            response = _make_request(http_session, base_url, case, timeout)
        except requests.RequestException as e:
            pytest.fail("请求异常: %s" % e)

        print("\n[反向-缺参] [%s] %s%s" % (case["method"], base_url, case["path"]))
        print("  Missing Params: %s" % case["missing"])
        print("  Status: %d" % response.status_code)

        kind, code, message = _report_negative_result(response)

        # 已确认后端对该参数有默认值兜底（接口文档标了必填，实现里其实可选）。
        # 这类接口的预期是"成功"，缺参返回错误才算回归。
        if case.get("has_backend_default"):
            assert kind is None, \
                "该接口已确认有默认值兜底，缺少 %s 时应返回成功，实际: kind=%s, code=%s, HTTP %d, message=%s" % (
                    case["missing"], kind, code, response.status_code, message)
            print("  [符合预期] 缺参走默认值兜底，返回成功")
            return

        if kind is None:
            # 缺少必填参数仍然成功，可能后端有默认值兜底
            pytest.xfail("缺少必填参数但返回成功，可能后端有默认值或参数非真正必填")
        elif kind == "biz_error":
            print("  [符合预期] 返回错误码: code=%s, message=%s" % (code, message))
        elif kind == "http_error":
            print("  [符合预期] HTTP 错误码: %d" % response.status_code)
        else:
            print("  [注意] 缺少必填参数但未返回明显错误，Status=%d" % response.status_code)

    @pytest.mark.negative
    @pytest.mark.parametrize("case", _CASES_INVALID, ids=_ids(_CASES_INVALID))
    def test_invalid_param_format(self, http_session, base_url, case, timeout):
        """
        传入非法格式参数
        - 对定义了 pattern/expression 校验规则的参数传入违规值
        - 期望返回参数校验错误
        """
        _skip_if_unauthorized(case)

        try:
            response = _make_request(http_session, base_url, case, timeout)
        except requests.RequestException as e:
            pytest.fail("请求异常: %s" % e)

        print("\n[反向-非法] [%s] %s%s" % (case["method"], base_url, case["path"]))
        print("  Invalid Params: %s" % {k: case["params"].get(k) for k in case["invalid"]})
        print("  Status: %d" % response.status_code)

        kind, code, message = _report_negative_result(response)
        if kind is None:
            pytest.xfail("传入非法参数但返回成功，可能校验规则未生效或宽松匹配")
        elif kind == "biz_error":
            print("  [符合预期] 返回错误码: code=%s, message=%s" % (code, message))
        elif kind == "http_error":
            print("  [符合预期] HTTP 错误码: %d" % response.status_code)
        else:
            print("  [注意] 传入非法参数但未返回明显错误，Status=%d" % response.status_code)


# ==================== 命令行执行入口 ====================

def run_pytest(args_list, description=""):
    """调用 pytest 执行测试"""
    cmd = [sys.executable, "-m", "pytest"] + args_list
    print("\n" + "=" * 60)
    if description:
        print("[%s]" % description)
    print("命令: %s" % " ".join(cmd))
    print("=" * 60 + "\n")
    return subprocess.run(cmd, cwd=Path(__file__).parent).returncode


def main():
    parser = argparse.ArgumentParser(
        description="datastat 接口自动化测试执行入口",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
示例:
  py test_cases.py                          # 正向测试
  py test_cases.py --negative               # 反向测试
  py test_cases.py --all --report           # 全部测试 + HTML 报告
  py test_cases.py --module=datastat        # 指定模块
  py test_cases.py --base-url=http://xxx    # 自定义地址
        """,
    )
    parser.add_argument("--negative", action="store_true", help="执行反向测试")
    parser.add_argument("--positive", action="store_true", help="执行正向测试（默认）")
    parser.add_argument("--all", action="store_true", help="执行所有测试（正向+反向）")
    parser.add_argument("--report", action="store_true", help="生成 HTML 测试报告")
    parser.add_argument("--module", default="", help="指定测试模块（如 datastat, TTFHW）")
    parser.add_argument("--base-url", default=DEFAULT_BASE_URL, help="API 基础地址")
    parser.add_argument("--timeout", type=int, default=DEFAULT_TIMEOUT, help="请求超时（秒）")
    parser.add_argument("--auth-token", default="", help="认证 Token")
    parser.add_argument("--verbose", "-v", action="store_true", help="详细输出")
    parser.add_argument("--maxfail", type=int, default=0, help="最大失败次数（0=不限制）")
    parser.add_argument("-n", "--numprocesses", default="", help="并发进程数（需 pytest-xdist）")
    parser.add_argument("--run-unauthorized", action="store_true",
                        help="强制执行需鉴权的用例（默认在未提供凭证时跳过）")
    args = parser.parse_args()

    if not any([args.negative, args.positive, args.all]):
        args.positive = True

    # 选择 marker：--all 时用单次调用同时收集正反向，避免两轮 pytest 互相覆盖 HTML 报告
    if args.all:
        marker = "positive or negative"
        description = "全量测试（正向 + 反向）"
    elif args.negative:
        marker = "negative"
        description = "反向测试"
    else:
        marker = "positive"
        description = "正向测试"

    pytest_args = [
        str(Path(__file__)),
        "-m", marker,
        "--base-url", args.base_url,
        "--timeout", str(args.timeout),
    ]
    if args.module:
        pytest_args.extend(["--module", args.module])
    if args.auth_token:
        pytest_args.extend(["--auth-token", args.auth_token])
    if args.verbose:
        pytest_args.append("-v")
    if args.maxfail > 0:
        pytest_args.extend(["--maxfail", str(args.maxfail)])
    if args.numprocesses:
        pytest_args.extend(["-n", args.numprocesses, "--dist", "load"])
    if args.run_unauthorized:
        pytest_args.append("--run-unauthorized")

    if args.report:
        report_file = "test_report_%s.html" % args.module if args.module else "test_report.html"
        pytest_args.extend(["--html=" + report_file, "--self-contained-html"])
        print("[报告] 将生成 HTML 报告: %s" % report_file)

    code = run_pytest(pytest_args, description)

    print("\n" + "=" * 60)
    print("[测试执行完成]")
    print("结果: %s" % ("存在失败的测试用例" if code != 0 else "全部通过"))
    sys.exit(1 if code != 0 else 0)


if __name__ == "__main__":
    main()
